import{_ as a,o as r,c as t,aF as o}from"./chunks/framework.CNkxH4QO.js";const h=JSON.parse('{"title":"krawler-firms","description":"A Krawler based service to download data from the Fire Information for Resource Management System (FIRMS)","frontmatter":{"title":"krawler-firms","description":"A Krawler based service to download data from the Fire Information for Resource Management System (FIRMS)"},"headers":[],"relativePath":"packages/krawler-firms/index.md","filePath":"packages/krawler-firms/index.md"}'),i={name:"packages/krawler-firms/index.md"};function s(d,e,n,l,c,f){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="krawler-firms" tabindex="-1">krawler-firms <a class="header-anchor" href="#krawler-firms" aria-label="Permalink to &quot;krawler-firms&quot;">​</a></h1><p><em>A Krawler based service to download data from the Fire Information for Resource Management System (FIRMS)</em></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The <strong>krawler-firms</strong> job allows to scrape data from the FIRMS using the following url: <a href="https://firms.modaps.eosdis.nasa.gov/data/active_fire/suomi-npp-viirs-c2/csv/SUOMI_VIIRS_C2_Global_7d.csv" target="_blank" rel="noreferrer">https://firms.modaps.eosdis.nasa.gov/data/active_fire/suomi-npp-viirs-c2/csv/SUOMI_VIIRS_C2_Global_7d.csv</a>. The downloaded data are stored within a <a href="https://www.mongodb.com/" target="_blank" rel="noreferrer">MongoDB</a> database:</p><ul><li>the <code>firms</code> collection stores the Thermal Hotspots and Fire Activity data</li></ul><p>All records are stored in <a href="https://fr.wikipedia.org/wiki/GeoJSON" target="_blank" rel="noreferrer">GeoJson</a> format.</p><p>The job is executed according a specific cron expression. By default, every hour.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>DB_URL</code></td><td>The mongoDB database URL. The default value is <code>mongodb://127.0.0.1:27017/kano</code></td></tr><tr><td><code>DEBUG</code></td><td>Enables debug output. Set it to <code>krawler*</code> to enable full output. By default it is undefined.</td></tr></tbody></table>',9)])])}const p=a(i,[["render",s]]);export{h as __pageData,p as default};
